from rlm_mcp_server.engine import RLMEngine from rlm_mcp_server.models import ( AggregateInput, AggregateOperation, AnalyzeInput, ConstraintInput, ContextTarget, SearchRegexInput, SearchSemanticInput, SegmentInput, )
def test_context_info_and_peek_text() -> None: e = RLMEngine() target = ContextTarget(text="alpha\nbeta\ngamma")
info = e.context_info(target) assert info["line_count"] == 3
peek = e.context_peek(target=target, line_start=1, line_end=2) assert peek["text"] == "beta"
def test_regex_and_semantic_search() -> None: e = RLMEngine() target = ContextTarget(text="Paris is in France. Rome is in Italy.")
regex = e.search_regex(SearchRegexInput(target=target, pattern=r"\\bFrance\\b")) assert regex["count"] == 1
sem = e.search_semantic(SearchSemanticInput(target=target, query="capital france", top_k=1, chunk_size=20)) assert sem["results"]
def test_segment_state_aggregate_verify_and_output() -> None: e = RLMEngine() text = "# A\none two\n\n# B\nthree four" target = ContextTarget(text=text)
seg = e.segment(SegmentInput(target=target, strategy="markdown_headers", output_var="chunks")) assert seg["count"] == 2
e.state_set("nums", [1, 2, 2, 3]) agg = e.transform_aggregate(AggregateInput(state_var="nums", operation=AggregateOperation.frequencies)) assert agg["value"]["2"] == 2
check = e.verify_constraint_check(ConstraintInput(state_var="nums", expected_type="list", min_items=3)) assert check["ok"] is True
out = e.output_return_var("nums") assert out["value"] == [1, 2, 2, 3]
def test_fallback_subcall_analyze() -> None: e = RLMEngine() target = ContextTarget(text="MCP enables tools. RLM uses recursive calls over chunks.") out = e.fallback_analyze(AnalyzeInput(query="What does RLM use?", target=target)) assert out.answer assert 0.0 <= out.confidence <= 1.0

